const items = $input.all();

for (const item of items) {
  const body = item.json.body || item.json;

  const cardId = body.cardId || '';
  const bodyText = body.content || body.bodyText || '';
  const title = body.title || '';
  const mediaType = body.mediaType || 'none';
  const mediaUrl = body.mediaUrl || '';

  let imageUrl = '';
  let videoUrl = '';
  if (mediaType === 'image') {
    imageUrl = mediaUrl;
  } else if (mediaType === 'video') {
    videoUrl = mediaUrl;
  }
  if (!imageUrl && !videoUrl) {
    imageUrl = body.imageUrl || '';
    videoUrl = body.videoUrl || '';
  }

  // ── Parse scheduled_publish_time ──────────────────────────────────────
  const publishType = body.publishType || 'immediate';
  let isScheduled = publishType === 'scheduled';
  let scheduledPublishTime = null;

  const parseScheduledTime = (raw) => {
    if (!raw) return null;
    const hasTimezone = /[Zz]|[+\-]\d{2}:?\d{2}$/.test(String(raw));
    const normalized = hasTimezone ? raw : `${raw}+07:00`;
    const d = new Date(normalized);
    return isNaN(d.getTime()) ? null : Math.floor(d.getTime() / 1000);
  };

  if (body.scheduledTime) {
    scheduledPublishTime = parseScheduledTime(body.scheduledTime);
    if (scheduledPublishTime) isScheduled = true;
  } else if (body.scheduledDate) {
    const timeStr = body.scheduledHour
      ? `${body.scheduledDate}T${body.scheduledHour}`
      : `${body.scheduledDate}T00:00:00`;
    scheduledPublishTime = parseScheduledTime(timeStr);
    if (scheduledPublishTime) isScheduled = true;
  }

  // ── Validate Facebook API constraints ─────────────────────────────────
  if (isScheduled && scheduledPublishTime) {
    const nowSec = Math.floor(Date.now() / 1000);
    const minAllowed = nowSec + 10 * 60;
    const maxAllowed = nowSec + 30 * 24 * 3600;
    if (scheduledPublishTime < minAllowed) {
      scheduledPublishTime = minAllowed + 60;
    } else if (scheduledPublishTime > maxAllowed) {
      throw new Error('Thời gian lên lịch không được vượt quá 30 ngày từ hiện tại.');
    }
  }

  // ── Auth & API URL ─────────────────────────────────────────────────────
  const integration = body.integration || {};
  const pageId = body.pageId || integration.pageId;
  const accessToken = body.accessToken || integration.pageAccessToken;

  if (!pageId || !accessToken) {
    throw new Error('Missing Facebook Page ID or Access Token.');
  }

  let facebookApiUrl = '';
  let requestBody = {};
  let postType = 'text';

  if (videoUrl && videoUrl.trim().startsWith('http')) {
    postType = 'video';
    facebookApiUrl = `https://graph.facebook.com/v19.0/${pageId}/videos`;
    requestBody = { description: bodyText, file_url: videoUrl, access_token: accessToken };
    if (isScheduled && scheduledPublishTime) {
      requestBody.published = false;
      requestBody.scheduled_publish_time = scheduledPublishTime;
    } else {
      requestBody.published = true;
    }
  } else if (imageUrl && imageUrl.trim().startsWith('http')) {
    postType = 'image';
    facebookApiUrl = `https://graph.facebook.com/v19.0/${pageId}/photos`;
    requestBody = { caption: bodyText, url: imageUrl, access_token: accessToken };
    if (isScheduled && scheduledPublishTime) {
      requestBody.published = false;
      requestBody.scheduled_publish_time = scheduledPublishTime;
    } else {
      requestBody.published = true;
    }
  } else {
    postType = 'text';
    facebookApiUrl = `https://graph.facebook.com/v19.0/${pageId}/feed`;
    requestBody = { message: bodyText, access_token: accessToken };
    if (isScheduled && scheduledPublishTime) {
      requestBody.published = false;
      requestBody.scheduled_publish_time = scheduledPublishTime;
    }
  }

  const callbackUrl =
    body.callbackUrl ||
    'https://api.igentechsolutions.com/api/v1/facebook/n8n-callback';

  item.json.preparedData = {
    cardId,
    pageId,
    postType,
    accessToken,
    apiUrl: facebookApiUrl,
    body: requestBody,
    callbackUrl,
    isScheduled,
  };
}

return items;

const items = $input.all();

for (const item of items) {
  const data = item.json;
  let videoStatus = 'processing';

  if (data.error) {
    const errMsg = String(data.error.message || data.error.type || '').toLowerCase();
    // FB returns this error when 'is_published' field doesn't exist on a published post
    if (errMsg.includes('is_published') || errMsg.includes('nonexisting field') || errMsg.includes('unknown field')) {
      videoStatus = 'ready';
    } else {
      videoStatus = 'failed';
    }
  } else if (data.status && data.status.video_status) {
    const vs = String(data.status.video_status).toLowerCase();
    if (vs === 'ready') {
      videoStatus = 'ready';
    } else if (vs === 'error' || vs === 'failed' || vs === 'invalid') {
      videoStatus = 'failed';
    } else {
      // processing, pending, uploading, etc.
      videoStatus = 'processing';
    }
  } else if (data.is_published === true || (data.id && data.is_published !== false)) {
    videoStatus = 'ready';
  }

  item.json.videoStatusNormalized = videoStatus;
}

return items;
